					data={standingsQuery.data ?? []}
					keyExtractor={(item) => item.id}
					renderItem={({ item, index }) => (
						<StandingRow item={item as unknown as StandingItem} rank={index + 1} />
					)}
					contentContainerStyle={styles.list}
				/>
			</SafeAreaView>
		</ThemedView>
	);
}
```

